// The browser's daemon (ADR 0042): `txtodo-web` in a dedicated Worker, the only context where
// OPFS sync access handles (SQLite's storage here) exist. The page posts `{ id, cmd, args }`; the
// Worker answers `{ id, ok }` or `{ id, err }`, then posts `{ changes }` when a call changed a list.
// The wasm is generated by `npm run build:web-host` into `../web-host/` (gitignored).
// Refs: https://developer.mozilla.org/en-US/docs/Web/API/DedicatedWorkerGlobalScope ·
// https://developer.mozilla.org/en-US/docs/Web/API/FileSystemFileHandle/createSyncAccessHandle
import init, { WebHost } from "../web-host/txtodo_web.js";

/** The one database file in the OPFS pool. */
const DB = "/txtodo.db";
/** Open attempts, `RETRY_MS` apart. Sync access handles are exclusive, so an open fails while
 * another Worker holds them: a second tab, or (not seen in Chromium, but nothing forbids it) the
 * last page's Worker during a reload. */
const OPEN_ATTEMPTS = 20;
const RETRY_MS = 250;

interface Request {
	id: number;
	cmd: string;
	args: unknown;
}

async function openHost(): Promise<WebHost> {
	await init();
	let last: unknown;
	for (let attempt = 0; attempt < OPEN_ATTEMPTS; attempt++) {
		try {
			return await WebHost.open(DB);
		} catch (err) {
			last = err;
			await new Promise((resolve) => setTimeout(resolve, RETRY_MS));
		}
	}
	// Still held after five seconds: another tab owns the lists (one owner at a time).
	console.error("web host: open failed", String(last));
	throw new Error(`the lists are open in another tab or window (${String(last)})`);
}

// Opened once; every call waits on it. A failed open answers every call with its error.
const opened: Promise<WebHost> = openHost();

self.onmessage = async (e: MessageEvent<Request>) => {
	const { id, cmd, args } = e.data;
	try {
		const host = await opened;
		const ok: unknown = JSON.parse(host.call(cmd, JSON.stringify(args ?? null)));
		self.postMessage({ id, ok });
		const changes: unknown[] = JSON.parse(host.takeChanges());
		if (changes.length > 0) self.postMessage({ changes });
	} catch (err) {
		self.postMessage({ id, err: String(err) });
	}
};
